int contarCriticos(int semilla) {
  if (semilla == 0) {
    return 0;
  }

  if (semilla % 10 % 2 == 1) {
    return 1 + contarCriticos(semilla / 10);
  }

  return contarCriticos(semilla / 10);
}

void aplicarDano(int vidas[], int n, int danoTotal) {
  if (n == 0) {
    return;
  }

  vidas[n - 1] = vidas[n - 1] - danoTotal;

  if (vidas[n - 1] < 0) {
    vidas[n - 1] = 0;
  }

  aplicarDano(vidas, n - 1, danoTotal);
}

int main() {
  int vidas[50];
  int n;
  int semilla;
  int i;
  int derrotados = 0;

  do {
    printf("Enemigos (1 a 50): ");
    scanf("%d", &n);
  } while (n < 1 || n > 50);

  for (i = 0; i < n; i++) {
    printf("Vida Enemigo %d: ", i + 1);
    scanf("%d", &vidas[i]);
  }

  do {
    printf("Semilla: ");
    scanf("%d", &semilla);
  } while (semilla <= 0);

  int danoTotal = 30 + 10 * contarCriticos(semilla);

  aplicarDano(vidas, n, danoTotal);
  printf("Dano total: %d\n", danoTotal);

  printf("Vida restante enemigos:\n");

  for (i = 0; i < n; i++) {
    printf("Vida Enemigo %d: %d\n", i + 1, vidas[i]);

    if (vidas[i] == 0) {
      derrotados++;
    }
  }

  printf("Derrotados: %d\n", derrotados);

  return 0;
}

